from pathlib import Path

# Apply only to the clean tree AFTER v0.7's successful customization.
def change(path,old,new):
    p=Path(path); text=p.read_text()
    count=text.count(old)
    if count!=1:
        raise SystemExit(f"Patch refused: {path}: expected 1 exact match, got {count} for {old[:60]!r}")
    p.write_text(text.replace(old,new))

change('src/evo_settings.c',
       '#include "include/pad.h"',
       '#include "include/pad.h"\n#include "include/sound.h"')
change('src/evo_settings.c',
       '    "Background music",',
       '    "Musica rap (BGM)",')
change('src/evo_ui.c',
       '"Sons do menu", "Musica de fundo", "Ordem automatica"',
       '"Sons do menu", "Batida rap (BGM)", "Ordem automatica"')
change('src/evo_settings.c',
       '    return saveConfig(CONFIG_OPL, 0);',
       '''    /* SD Ceara Games: external OGG audio, not baked into game loader.
     * The native BGM setting keeps ownership of on/off and persistence. */
    if (gDefaultBGMPath[0] == '\\0')
        snprintf(gDefaultBGMPath, sizeof(gDefaultBGMPath),
                 "mass0:/SDCEARA/bgm.ogg");

    /* Let the existing OPL audio engine start/stop the loop immediately
     * after an explicit Save, without altering controller or launch paths. */
    if (gEnableBGM) {
        if (!isBgmPlaying())
            bgmStart();
    } else if (isBgmPlaying()) {
        bgmStop();
    }

    return saveConfig(CONFIG_OPL, 0);''')

